(function(){
  function df(text){
    var lines=String(text||'').split(/\r?\n/).filter(function(s){return s.trim()&&!/Filesystem/.test(s);});
    return lines.map(function(l){ var p=l.split(/\s+/); return {filesystem:p[0], size:p[1], used:p[2], avail:p[3], use:p[4], mounted:p[5]}; });
  }
  function ls(text){
    var lines=String(text||'').split(/\r?\n/).filter(function(s){return /^[/\-]/.test(s);});
    return lines.map(function(l){ var p=l.split(/\s+/); return {perm:p[0], links:p[1], owner:p[2], group:p[3], size:p[4], name:p[p.length-1]}; });
  }
  function uptime(text){
    var s=String(text||'');
    var m=s.match(/load average:\s*([\d.]+),\s*([\d.]+),\s*([\d.]+)/);
    var up=s.match(/up\s+(.+?),\s+\d+\s+user/);
    return {uptime: up?up[1]:null, load: m?[m[1],m[2],m[3]].map(Number):[]};
  }
  function ping(text){
    var lines=String(text||'').split(/\r?\n/), rtt=[];
    lines.forEach(function(l){ var m=l.match(/time=([\d.]+)\s*ms/); if(m) rtt.push(Number(m[1])); });
    var loss=String(text||'').match(/(\d+)% packet loss/);
    return {rtt:rtt, loss: loss?loss[1]+'%':null};
  }
  function ps(text){
    var lines=String(text||'').split(/\r?\n/).filter(function(s){return /^\s*\d+/.test(s);});
    return lines.map(function(l){ var p=l.trim().split(/\s+/); return {pid:p[0], tty:p[1], time:p[2], cmd:p.slice(3).join(' ')}; });
  }
  function convert(cmd, text){
    cmd=(cmd||'').toLowerCase();
    if(cmd==='df') return {value: df(text)};
    if(cmd==='ls') return {value: ls(text)};
    if(cmd==='uptime') return {value: uptime(text)};
    if(cmd==='ping') return {value: ping(text)};
    if(cmd==='ps') return {value: ps(text)};
    return {error:'暂不支持的命令: '+cmd+'（支持 df/ls/uptime/ping/ps）'};
  }
  function wrap(fn){ return function(t){ try{ return {value: fn(t)}; }catch(e){ return {error:'解析失败: '+e.message}; } }; }
  var API={convert:convert, df:wrap(df), ls:wrap(ls), uptime:wrap(uptime), ping:wrap(ping), ps:wrap(ps)};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__JcForge__=API;
})();
